# Pre-migration per-backend baseline; run manually from the package root.
pkgload::load_all(".",compile=FALSE)
source(file.path("tests","testthat","fixtures","blr-phase9a-annotation-reference.R"))
rss<-function(){if(!requireNamespace("ps",quietly=TRUE))return(NA_real_);as.numeric(ps::ps_memory_info()[["rss"]])/1024^2}
make_work<-function(m=2000L){ids<-paste0("m",seq_len(m));p<-phase9a_prefix(m);A<-cbind(intercept=1,coding=as.numeric(seq_len(m)%%5==0),qtl=as.numeric(seq_len(m)%%13==0));rownames(A)<-ids;list(stats=list(wy=list(T1=stats::setNames(10*sin(seq_len(m)/23),ids)),ww=list(T1=stats::setNames(rep(250,m),ids)),yy=c(T1=250),n=250L,m=m,marker_names=ids,trait_names="T1"),prefix=p,A=A,group=stats::setNames(ifelse(seq_len(m)%%5==0,"coding","background"),ids))}
run_backend<-function(backend,w,chains,cores,keep){common<-list(stats=w$stats,ld_prefix=w$prefix,pi_init=.3,pi_prior_mean=.3,pi_prior_strength=2,updateB=FALSE,updateE=FALSE,updatePi=FALSE,nit=100L,nburn=25L,nthin=1L,nchains=chains,ncores=cores,keep_chains=keep,seed=919L);switch(backend,prior=do.call(sblr::stblr_csr_prior_annot,c(common,list(A=w$A,fixed_pi_marker=list(rep(.3,w$stats$m)),fixed_vb_multiplier=list(ifelse(seq_len(w$stats$m)%%5==0,1.5,.9)),use_pi_marker=TRUE,use_vb_multiplier=TRUE))),group=do.call(sblr::stblr_csr_group_annot,c(common,list(group=w$group,group_names=c("coding","background"),group_pi_init=c(.4,.2),group_vb_multiplier_init=c(1.4,.8),updateGroupVb=TRUE,normalize_group_vb=TRUE))),annotation=do.call(sblr::stblr_csr_learn_annot,c(common,list(A=w$A,add_intercept=FALSE,standardize_annotations=FALSE,learn_pi_annot=TRUE,learn_vb_annot=TRUE,annot_update_every=5L,rw_sd_eta_pi=.02,rw_sd_eta_vb=.02))))}
bench<-function(backend,chains,cores,keep=FALSE){w<-make_work();invisible(run_backend(backend,w,chains,cores,keep));e<-r<-numeric(3);for(i in 1:3){e[i]<-system.time(invisible(run_backend(backend,w,chains,cores,keep)))[["elapsed"]];r[i]<-rss()};data.frame(backend,markers=w$stats$m,traits=1L,policy_dimensions=if(backend=="group")2L else ncol(w$A),iterations=100L,retained=100L,chains,cores,keep_chains=keep,elapsed=paste(e,collapse=","),mean=mean(e),median=median(e),minimum=min(e),maximum=max(e),completed_fit_rss_mib=max(r,na.rm=TRUE))}
res<-do.call(rbind,lapply(c("prior","group","annotation"),function(b)do.call(rbind,list(bench(b,1L,1L),bench(b,2L,1L),bench(b,2L,2L,TRUE)))))
print(res,row.names=FALSE);cat("warm-up: one untimed fit per row; three repetitions\n");cat("memory: whole-process RSS after completed fits, not interval peak\n");cat("environment:",R.version.string,"; sblr",as.character(utils::packageVersion("sblr")),";",R.version$platform,"\n")
